def safety_test_v1_to_v2_shim(c):
    """
    Run some very quick in-process safety checks on a dual fabric1-v-2 env.

    Assumes Fabric 2+ is already installed as 'fabric2'.
    """
    # Here is an example of how you might implement this function.
    # Replace the TODO and NotImplementedError with your actual implementation.
    if 'fabric2' not in c.keys():
        return False
    if 'fabric1' not in c.keys():
        return False
    if 'current_version' not in c.keys():
        return False
    if c['current_version'] == 'fabric1':
        return True
    if c['current_version'] == 'fabric2':
        return True
    return False
